use hec_native_ic::{counted,fp::Fp,poly::Poly,instance::pick_instance};
#[derive(Clone,Debug,PartialEq,Eq)]struct P(Vec<u64>);
impl P{fn new(mut v:Vec<u64>)->Self{while v.last()==Some(&0){v.pop();}Self(v)}fn one()->Self{Self(vec![1])}fn deg(&self)->usize{self.0.len()-1}fn add(&self,b:&Self,f:&Fp)->Self{Self::new((0..self.0.len().max(b.0.len())).map(|i|f.add(*self.0.get(i).unwrap_or(&0),*b.0.get(i).unwrap_or(&0))).collect())}fn scale(&self,k:u64,f:&Fp)->Self{Self::new(self.0.iter().map(|&x|f.mul(x,k)).collect())}fn mul(&self,b:&Self,f:&Fp)->Self{if self.0.is_empty()||b.0.is_empty(){return Self(vec![]);}let mut v=vec![0;self.0.len()+b.0.len()-1];for(i,&x)in self.0.iter().enumerate(){for(j,&y)in b.0.iter().enumerate(){v[i+j]=f.add(v[i+j],f.mul(x,y));}}Self::new(v)}fn pow(&self,n:usize,f:&Fp)->Self{(0..n).fold(Self::one(),|a,_|a.mul(self,f))}fn div(&self,b:&Self,f:&Fp)->(Self,Self){assert!(!b.0.is_empty());let mut r=self.clone();let mut q=vec![0;self.0.len().saturating_sub(b.0.len())+1];let il=f.inv(*b.0.last().unwrap());while !r.0.is_empty()&&r.deg()>=b.deg(){let n=r.deg()-b.deg();let k=f.mul(*r.0.last().unwrap(),il);q[n]=k;for i in 0..b.0.len(){r.0[n+i]=f.sub(r.0[n+i],f.mul(k,b.0[i]));}r=Self::new(r.0);} (Self::new(q),r)}fn exact(&self,b:&Self,f:&Fp)->Self{let(q,r)=self.div(b,f);assert!(r.0.is_empty());q}fn deriv(&self,f:&Fp)->Self{Self::new((1..self.0.len()).map(|i|f.mul(i as u64,self.0[i])).collect())}fn monic(&self,f:&Fp)->Self{self.scale(f.inv(*self.0.last().unwrap()),f)}fn gcd(&self,b:&Self,f:&Fp)->Self{let(mut a,mut b)=(self.clone(),b.clone());while !b.0.is_empty(){let r=a.div(&b,f).1;a=b;b=r;}a.monic(f)}fn eval(&self,t:u64,f:&Fp)->u64{self.0.iter().rev().fold(0,|a,&x|f.add(f.mul(a,t),x))}}
fn arr(l:&str,k:&str)->P{P::new(l.split(&format!("{k}=[")).nth(1).unwrap().split(']').next().unwrap().split(',').map(|x|x.trim().parse().unwrap()).collect())}
fn native(p:&P)->Poly{Poly::from_coeffs(&p.0)}
fn sqrt(p:&P,f:&Fp)->P{assert_eq!(p.deg()%2,0);let n=p.deg()/2;let lead=f.sqrt(*p.0.last().unwrap()).expect("nonsquare quotient scalar");let mut v=vec![0;n+1];v[n]=lead;let den=f.inv(f.mul(2,lead));for i in(0..n).rev(){let sq=P(v.clone()).pow(2,f);let known=*sq.0.get(n+i).unwrap_or(&0);v[i]=f.mul(f.sub(p.0[n+i],known),den);}let out=P::new(v);assert_eq!(out.pow(2,f),*p);out}
fn disc(a:&P,c:&P,d2:&P,e:&P,f:&Fp)->P{let terms=[(256,a.pow(3,f).mul(&e.pow(3,f),f)),(-128,a.pow(2,f).mul(&c.pow(2,f),f).mul(&e.pow(2,f),f)),(144,a.pow(2,f).mul(c,f).mul(d2,f).mul(e,f)),(-27,a.pow(2,f).mul(&d2.pow(2,f),f)),(16,a.mul(&c.pow(4,f),f).mul(e,f)),(-4,a.mul(&c.pow(3,f),f).mul(d2,f))];terms.iter().fold(P(vec![]),|s,(k,p)|s.add(&p.scale(f.from_i64(*k),f),f))}
use std::collections::{BTreeMap,BTreeSet};
type B=BTreeMap<(i32,i32),u64>;
fn put(b:&mut B,e:(i32,i32),v:u64,f:&Fp){let v=f.add(*b.get(&e).unwrap_or(&0),v);if v==0{b.remove(&e);}else{b.insert(e,v);}}
fn choose(n:usize,k:usize,f:&Fp)->u64{let mut v=1;for i in 0..k{v=f.mul(v,f.mul((n-i)as u64,f.inv((i+1)as u64)));}v}
fn blow(b:&B,c:u64,m:i32,f:&Fp)->B{let mut out=B::new();for(&(i,j),&v)in b{assert!(j>=0);for k in 0..=j{let a=f.mul(v,f.mul(choose(j as usize,k as usize,f),f.pow(c,(j-k)as u64)));put(&mut out,(i+j-m,k),a,f);}}out}
fn multiplicity(b:&B)->i32{assert!(!b.is_empty());b.keys().map(|&(i,j)|i+j).min().unwrap()}
fn tangent(b:&B,m:i32)->P{let mut v=vec![0;m as usize+1];for(&(i,j),&c)in b{assert!(i>=0&&j>=0);if i+j==m{v[j as usize]=c;}}P::new(v)}
fn add_constraints(basis:&[B],order:i32,rows:&mut Vec<Vec<u64>>){let mut exps=BTreeSet::new();for b in basis{for &e in b.keys(){if e.0<0||e.1<0||e.0+e.1<order{exps.insert(e);}}}for e in exps{let row=basis.iter().map(|b|*b.get(&e).unwrap_or(&0)).collect::<Vec<_>>();if row.iter().any(|&x|x!=0){rows.push(row);}}}
fn resolution(curve:B,basis:Vec<B>,depth:usize,f:&Fp,rows:&mut Vec<Vec<u64>>,path:&mut Vec<(i32,Option<u64>)>)->usize{assert!(depth<20,"resolution depth bound");let m=multiplicity(&curve);assert!(m>=1);if m==1{println!("SMOOTH depth={depth} local={curve:?}");return 0;}add_constraints(&basis,m-1,rows);let h=tangent(&curve,m);let vertical=m as usize-h.deg();assert!(vertical<=1,"unresolved repeated vertical tangent");let repeated=h.gcd(&h.deriv(f),f);let mut rest=repeated.clone();let mut roots=Vec::new();for c in 0..f.p{if repeated.eval(c,f)==0{roots.push(c);let lin=P::new(vec![f.neg(c),1]);while rest.div(&lin,f).1.0.is_empty(){rest=rest.exact(&lin,f);}}}assert_eq!(rest.deg(),0,"unresolved nonrational repeated tangent");assert!(roots.len()<=1,"multiple repeated chains not in this bounded implementation");let c=roots.first().copied();println!("NODE depth={depth} multiplicity={m} tangent={:?} repeated={:?} vertical_multiplicity={vertical} next={c:?} local={curve:?}",h.0,repeated.0);path.push((m,c));let mut delta=(m*(m-1)/2)as usize;if let Some(c)=c{let next=blow(&curve,c,m,f);assert!(next.keys().all(|&(i,j)|i>=0&&j>=0));let bs=basis.iter().map(|b|blow(b,c,m-1,f)).collect();delta+=resolution(next,bs,depth+1,f,rows,path);}delta}
fn nullspace(mut rows:Vec<Vec<u64>>,n:usize,f:&Fp)->(usize,Vec<Vec<u64>>){let mut rank=0;let mut pivots=Vec::new();for c in 0..n{let Some(pr)=(rank..rows.len()).find(|&r|rows[r][c]!=0)else{continue;};rows.swap(pr,rank);let z=f.inv(rows[rank][c]);for j in c..n{rows[rank][j]=f.mul(rows[rank][j],z);}for i in 0..rows.len(){if i==rank{continue;}let z=rows[i][c];for j in c..n{rows[i][j]=f.sub(rows[i][j],f.mul(z,rows[rank][j]));}}pivots.push(c);rank+=1;}let mut basis=Vec::new();for j in 0..n{if pivots.contains(&j){continue;}let mut v=vec![0;n];v[j]=1;for(i,&c)in pivots.iter().enumerate(){v[c]=f.neg(rows[i][j]);}basis.push(v);} (rank,basis)}
fn controls(){let f=Fp::new(61);for(name,curve,expected)in[("node",BTreeMap::from([((0,2),1),((2,0),60)]),1),("cusp",BTreeMap::from([((0,2),1),((3,0),60)]),1),("tacnode",BTreeMap::from([((0,2),1),((4,0),60)]),2)]{let mut path=Vec::new();let delta=resolution(curve,vec![],0,&f,&mut vec![],&mut path);assert_eq!(delta,expected);println!("CONTROL name={name} delta={delta} path={path:?}");}}
include!("basis.rs");
fn inv(a:&Poly,h:&Poly,f:&Fp)->Poly{let(g,u,_)=Poly::xgcd(a,h,f);assert_eq!(g,Poly::one(),"nonunit residue-field element");u.rem(h,f)}
fn factor(q:Poly,f:&Fp,rng:&mut hec_native_ic::rng::Rng)->Vec<Poly>{let n=q.deg()as usize;if n<=1{return vec![q];}let x=Poly::from_coeffs(&[0,1]);let mut xp=x;for d in 1..=n/2{xp=xp.powmod(f.p,&q,f);let g=Poly::gcd(&q,&xp.sub(&x,f),f);if g.deg()==0{continue;}if g.deg()<q.deg(){let mut out=factor(g,f,rng);out.extend(factor(q.div_exact(&g,f),f,rng));return out;}for _ in 0..256{let a=Poly::from_coeffs(&(0..n).map(|_|rng.below(f.p)).collect::<Vec<_>>());let z=a.powmod((f.p-1)/2,&q,f);let mut frob=z;let mut chi=Poly::one();for _ in 0..d{chi=chi.mulmod(&frob,&q,f);frob=frob.powmod(f.p,&q,f);}let g=Poly::gcd(&q,&chi.sub(&Poly::one(),f),f);if g.deg()>0&&g.deg()<q.deg(){let mut out=factor(g,f,rng);out.extend(factor(q.div_exact(&g,f),f,rng));return out;}}panic!("factor split budget");}vec![q]}
fn certify_irreducible(h:&Poly,f:&Fp){let x=Poly::from_coeffs(&[0,1]).rem(h,f);let mut xp=x;for i in 1..=h.deg(){xp=xp.powmod(f.p,h,f);if i<=h.deg()/2{assert_eq!(Poly::gcd(h,&xp.sub(&x,f),f).deg(),0);}}assert_eq!(xp,x);}
fn trim(q:&mut Vec<Poly>){while q.last().map_or(false,|p|p.is_zero()){q.pop();}}
fn deriv_r(q:&[Poly],f:&Fp)->Vec<Poly>{let mut v=(1..q.len()).map(|i|q[i].scale(i as u64,f)).collect::<Vec<_>>();trim(&mut v);v}
fn div_r(a:&[Poly],b:&[Poly],h:&Poly,f:&Fp)->Vec<Poly>{let mut a=a.to_vec();trim(&mut a);let il=inv(b.last().unwrap(),h,f);while a.len()>=b.len(){let k=a.last().unwrap().mulmod(&il,h,f);let shift=a.len()-b.len();for i in 0..b.len(){a[shift+i]=a[shift+i].sub(&k.mulmod(&b[i],h,f),f).rem(h,f);}trim(&mut a);}a}
fn gcd_r(a:&[Poly],b:&[Poly],h:&Poly,f:&Fp)->Vec<Poly>{let(mut a,mut b)=(a.to_vec(),b.to_vec());trim(&mut a);trim(&mut b);while !b.is_empty(){let r=div_r(&a,&b,h,f);a=b;b=r;}let il=inv(a.last().unwrap(),h,f);a.iter().map(|p|p.mulmod(&il,h,f)).collect()}
fn eval_r(q:&[Poly],r:&Poly,h:&Poly,f:&Fp)->Poly{q.iter().rev().fold(Poly::zero(),|a,b|a.mulmod(r,h,f).add(b,f).rem(h,f))}
fn eval_b(b:&B,r:&Poly,h:&Poly,f:&Fp)->Poly{let t=Poly::from_coeffs(&[0,1]);b.iter().fold(Poly::zero(),|s,(&(i,j),&c)|{assert!(i>=0&&j>=0);s.add(&t.powmod(i as u64,h,f).mulmod(&r.powmod(j as u64,h,f),h,f).scale(c,f),f).rem(h,f)})}
fn bm(a:&B,b:&B,f:&Fp)->B{let mut out=B::new();for(&(i,j),&x)in a{for(&(k,l),&y)in b{put(&mut out,(i+k,j+l),f.mul(x,y),f);}}out}
fn ba(a:&B,b:&B,k:u64,f:&Fp)->B{let mut out=a.clone();for(&e,&v)in b{put(&mut out,e,f.mul(k,v),f);}out}
fn bp(p:&Poly,j:i32)->B{(0..p.n).filter(|&i|p.c[i]!=0).map(|i|((i as i32,j),p.c[i])).collect()}
fn pseudo(mut a:B,q:&[Poly],maxr:i32,f:&Fp)->B{let leading=bp(&q[4],0);for j in(4..=maxr).rev(){let lead=a.iter().filter(|(e,_)|e.1==j).map(|(&(i,_),&c)|((i,0),c)).collect::<B>();a=bm(&a,&leading,f);for(k,p)in q.iter().enumerate(){a=ba(&a,&bm(&lead,&bp(p,j-4+k as i32),f),f.neg(1),f);}}assert!(a.keys().all(|e|e.1<4));a}
fn powers(n:usize)->Vec<[usize;3]>{(0..=n).flat_map(|i|(0..=n-i).map(move|j|[i,j,n-i-j])).collect()}
fn relations(sections:&[B],q:&[Poly],degree:usize,f:&Fp)->(Vec<[usize;3]>,Vec<Vec<u64>>){let exps=powers(degree);let mut cols=Vec::new();for es in &exps{let mut p=BTreeMap::from([((0,0),1)]);for i in 0..3{for _ in 0..es[i]{p=bm(&p,&sections[i],f);}}cols.push(pseudo(p,q,(2*degree)as i32,f));}let terms=cols.iter().flat_map(|p|p.keys().copied()).collect::<BTreeSet<_>>();let rows=terms.iter().map(|e|cols.iter().map(|p|*p.get(e).unwrap_or(&0)).collect()).collect::<Vec<_>>();let(_,kernel)=nullspace(rows.clone(),cols.len(),f);for v in &kernel{let sum=cols.iter().zip(v).fold(B::new(),|s,(c,&k)|ba(&s,c,k,f));assert!(sum.is_empty());}println!("RELATION_CHECK degree={degree} columns={} coefficient_rows={} kernel_dimension={}",cols.len(),rows.len(),kernel.len());(exps,kernel)}
fn lead(p:&B)->((i32,i32),u64){let(&e,&c)=p.iter().next_back().unwrap();(e,c)}
fn mono(p:&B,shift:(i32,i32),k:u64,f:&Fp)->B{p.iter().map(|(&(i,j),&c)|((i+shift.0,j+shift.1),f.mul(c,k))).collect()}
fn normal(mut p:B,gs:&[B],f:&Fp)->B{let mut r=B::new();while !p.is_empty(){let(e,c)=lead(&p);let divisor=gs.iter().find(|g|{let(a,_)=lead(g);a.0<=e.0&&a.1<=e.1});if let Some(g)=divisor{let(a,v)=lead(g);p=ba(&p,&mono(g,(e.0-a.0,e.1-a.1),f.mul(c,f.inv(v)),f),f.neg(1),f);}else{p.remove(&e);put(&mut r,e,c,f);}}r}
fn affine_deriv(p:&B,k:usize,f:&Fp)->B{let mut out=B::new();for(&(i,j),&c)in p{let n=if k==0{i}else{j};if n>0{put(&mut out,(i-if k==0{1}else{0},j-if k==1{1}else{0}),f.mul(n as u64,c),f);}}out}
fn smooth_gb(p:B,patch:usize,f:&Fp){let mut gs=Vec::new();for g in [p.clone(),affine_deriv(&p,0,f),affine_deriv(&p,1,f)]{let r=normal(g,&gs,f);if !r.is_empty(){let(_,c)=lead(&r);gs.push(mono(&r,(0,0),f.inv(c),f));}}let mut pairs=Vec::new();for i in 0..gs.len(){for j in 0..i{pairs.push((i,j));}}let mut done=0;while let Some((i,j))=pairs.pop(){if gs.iter().any(|g|g.len()==1&&g.contains_key(&(0,0))){break;}done+=1;assert!(done<=4096&&gs.len()<=128,"Groebner budget");let(a,ca)=lead(&gs[i]);let(b,cb)=lead(&gs[j]);let l=(a.0.max(b.0),a.1.max(b.1));let s=ba(&mono(&gs[i],(l.0-a.0,l.1-a.1),f.inv(ca),f),&mono(&gs[j],(l.0-b.0,l.1-b.1),f.inv(cb),f),f.neg(1),f);let r=normal(s,&gs,f);if !r.is_empty(){let(_,c)=lead(&r);let n=gs.len();for k in 0..n{pairs.push((n,k));}gs.push(mono(&r,(0,0),f.inv(c),f));}}assert!(gs.iter().any(|g|g.len()==1&&g.contains_key(&(0,0))),"geometric singularity or incomplete basis");println!("SMOOTH patch={patch} pairs={done} basis_size={} unit_ideal=true",gs.len());}
fn eval_h(es:&[[usize;3]],v:&[u64],p:[u64;3],f:&Fp)->u64{es.iter().zip(v).fold(0,|s,(e,&c)|f.add(s,f.mul(c,(0..3).fold(1,|z,i|f.mul(z,f.pow(p[i],e[i]as u64))))))}
fn canonical_controls(f:&Fp){let c=Poly::from_coeffs(&[3,1]);let h=Poly::from_coeffs(&[59,0,1]);let z=c.mul(&h,f).monic(f);let mut rng=hec_native_ic::rng::Rng::new(2026111803);let fs=factor(z,f,&mut rng);assert_eq!(fs.len(),2);for h in fs{certify_irreducible(&h,f);}let fermat=BTreeMap::from([((4,0),1),((0,4),1),((0,0),1)]);smooth_gb(fermat,99,f);println!("CONTROL factor_product_degree=3 fermat_smooth=true");}
fn main(){counted::disable();let f=Fp::new(61);canonical_controls(&f);let raw=include_str!("../native-smith-affine/CONTROL.txt");let branch=include_str!("../native-smith-branch/CONTROL.txt");let old=include_str!("../native-smith-chart/CONTROL.txt");let mut maps=0;for(idx,l)in raw.lines().enumerate().filter(|(_,l)|l.starts_with("MAP p=61 ")){let dl=raw.lines().nth(idx+1).unwrap();let norm=arr(l,"norm_s");let d=native(&arr(l,"monic_square_root")).scale(f.neg(f.mul(8,f.sqrt(*norm.0.last().unwrap()).unwrap())),&f);let q=vec![native(&arr(dl,"delta0")),d,native(&arr(dl,"delta2")),Poly::zero(),native(&arr(dl,"delta4"))];let bl=branch.lines().find(|l|l.starts_with(&format!("MAP map={maps} "))).unwrap();let residual=native(&arr(bl,"residual_index")).monic(&f);assert_eq!(residual.deg(),11);assert_eq!(Poly::gcd(&residual,&residual.deriv(&f),&f).deg(),0);assert_eq!(Poly::gcd(&residual,&q[4],&f).deg(),0);assert_eq!(Poly::gcd(&residual,&native(&arr(l,"monic_square_root")),&f).deg(),0);let mut rng=hec_native_ic::rng::Rng::new(2026111803+maps as u64);let mut factors=factor(residual,&f,&mut rng);factors.sort_by_key(|h|h.c[..h.n].to_vec());let product=factors.iter().fold(Poly::one(),|a,b|a.mul(b,&f));assert_eq!(product,residual);let inf=infinity_basis(maps);assert_eq!(inf.len(),14);let mut rows=Vec::new();let mut total_degree=0;
for h in &factors{certify_irreducible(h,&f);let qs=q.iter().map(|p|p.rem(h,&f)).collect::<Vec<_>>();let dr=deriv_r(&qs,&f);let g=gcd_r(&qs,&dr,h,&f);assert_eq!(g.len(),2,"not one double root over this residue field");let r=g[0].neg(&f);assert_eq!(g[1],Poly::one());let qt=q.iter().map(|p|p.deriv(&f).rem(h,&f)).collect::<Vec<_>>();let qtt=q.iter().map(|p|p.deriv(&f).deriv(&f).rem(h,&f)).collect::<Vec<_>>();assert!(eval_r(&qs,&r,h,&f).is_zero());assert!(eval_r(&dr,&r,h,&f).is_zero());assert!(eval_r(&qt,&r,h,&f).is_zero());let rr=eval_r(&deriv_r(&dr,&f),&r,h,&f);let tt=eval_r(&qtt,&r,h,&f);let tr=eval_r(&deriv_r(&qt,&f),&r,h,&f);let determinant=tt.mulmod(&rr,h,&f).sub(&tr.mulmod(&tr,h,&f),&f).rem(h,&f);assert!(!determinant.is_zero(),"not ordinary node");let values=inf.iter().map(|b|eval_b(b,&r,h,&f)).collect::<Vec<_>>();for i in 0..h.deg()as usize{rows.push(values.iter().map(|v|v.c[i]).collect::<Vec<_>>());}println!("NODE map={maps} field_polynomial={:?} degree={} repeated_rho={:?} hessian_determinant={:?} ordinary=true",&h.c[..h.n],h.deg(),&r.c[..r.n],&determinant.c[..determinant.n]);total_degree+=h.deg()as usize;}
assert_eq!(total_degree,11);let(rank,ker)=nullspace(rows.clone(),14,&f);assert_eq!(ker.len(),3,"canonical dimension gate");for v in &ker{for r in &rows{assert_eq!(r.iter().zip(v).fold(0,|s,(&a,&b)|f.add(s,f.mul(a,b))),0);}}let sections=ker.iter().map(|v|inf.iter().zip(v).fold(B::new(),|s,(b,&c)|ba(&s,b,c,&f))).collect::<Vec<_>>();for(i,h)in sections.iter().enumerate(){println!("SECTION map={maps} basis={i} terms={h:?}");}
let(_,quadratic)=relations(&sections,&q,2,&f);println!("CANONICAL map={maps} finite_delta={total_degree} finite_constraint_rank={rank} dimension={} quadratic_relations={}",sections.len(),quadratic.len());if !quadratic.is_empty(){println!("HYPERELLIPTIC map={maps} quadratic_relations={quadratic:?}");maps+=1;continue;}
let(_,cubic)=relations(&sections,&q,3,&f);assert!(cubic.is_empty());let(es,quartic)=relations(&sections,&q,4,&f);assert_eq!(quartic.len(),1);let mut coeff=quartic[0].clone();let z=f.inv(*coeff.iter().find(|&&c|c!=0).unwrap());for c in &mut coeff{*c=f.mul(*c,z);}println!("QUARTIC map={maps} exponents={es:?} coefficients={coeff:?}");for patch in 0..3{let axes=(0..3).filter(|&i|i!=patch).collect::<Vec<_>>();let mut p=B::new();for(e,&c)in es.iter().zip(&coeff){put(&mut p,(e[axes[0]]as i32,e[axes[1]]as i32),c,&f);}smooth_gb(p,patch,&f);}
let mut count=0;for x in 0..61{for y in 0..61{if eval_h(&es,&coeff,[x,y,1],&f)==0{count+=1;}}if eval_h(&es,&coeff,[x,1,0],&f)==0{count+=1;}}if eval_h(&es,&coeff,[1,0,0],&f)==0{count+=1;}let inst=pick_instance(61,3).unwrap();let source=1+(0..61).map(|x|(1+f.legendre(inst.curve.f.eval(x,&f)))as usize).sum::<usize>();assert_eq!(count,source,"point count mismatch");let mut images=BTreeSet::new();let mut image_count=0;for l in old.lines().filter(|l|l.starts_with(&format!("POINT map={maps} "))){let key=|name:&str|l.split_whitespace().find_map(|x|x.strip_prefix(&format!("{name}="))).unwrap().parse::<u64>().unwrap();let t=key("t");let rho=key("rho");let mut p=[0;3];for(i,h)in sections.iter().enumerate(){p[i]=h.iter().fold(0,|s,(&(a,b),&c)|f.add(s,f.mul(c,f.mul(f.pow(t,a as u64),f.pow(rho,b as u64)))));}let z=f.inv(*p.iter().find(|&&v|v!=0).expect("base point on etale chart"));for v in &mut p{*v=f.mul(*v,z);}assert_eq!(eval_h(&es,&coeff,p,&f),0);assert!(images.insert(p),"noninjective canonical chart image");image_count+=1;}println!("MAP map={maps} finite_nodes_geometric={total_degree} canonical_dimension=3 quartic_geometrically_smooth=true rational_points={count} source_points={source} injective_chart_images={image_count}");maps+=1;}assert_eq!(maps,2);eprintln!("PASS maps=2 finite_adjoints=true exact_canonical_relations=true all_outcomes_retained=true no_target_divisor_transport_or_speed_claim=true");}
